    logic xs_subtractive_axi_bready;
    logic [$bits(subtractive_axi_rid_bridge_id)-1:0] xs_subtractive_axi_rid_bridge_id;
    logic [$bits(subtractive_axi_rid)-1:0] xs_subtractive_axi_rid;
    logic [$bits(subtractive_axi_rdata)-1:0] xs_subtractive_axi_rdata;
    logic [$bits(subtractive_axi_rresp)-1:0] xs_subtractive_axi_rresp;
    logic [$bits(subtractive_axi_rlast)-1:0] xs_subtractive_axi_rlast;
    logic [$bits(subtractive_axi_ruser)-1:0] xs_subtractive_axi_ruser;
    logic xs_subtractive_axi_rvalid;
    logic xs_subtractive_axi_rready;
    logic xs_subtractive_axi_bid_valid;
    logic xs_subtractive_axi_rid_valid;

    // ================================================================
    // Slave 0: ddr (32b)
    // ================================================================
    // Multi-master (2 masters) → ddr
    //   - cpu (rw)
    //   - dma (rw)

    wire cpu_32b_aw_to_ddr = (cpu_32b_aw.addr <= 32'h7fffffff);
    wire cpu_32b_ar_to_ddr = (cpu_32b_ar.addr <= 32'h7fffffff);
    wire dma_32b_aw_to_ddr = (dma_32b_aw.addr <= 32'h7fffffff);
    wire dma_32b_ar_to_ddr = (dma_32b_ar.addr <= 32'h7fffffff);

    // ---- AW arbiter for ddr: QoS + aging, round-robin ties, lock until handshake ----
    logic [1:0] ddr_aw_arb_req;
    assign ddr_aw_arb_req = {dma_32b_aw_to_ddr && dma_32b_awvalid, cpu_32b_aw_to_ddr && cpu_32b_awvalid};
    logic [0:0] ddr_aw_arb_lock, ddr_aw_arb_rr;
    logic ddr_aw_arb_locked;
    // QoS with aging (BRIDGE-017): effective priority = AxQOS + age,
    // age climbing one level every 2**4 cycles a request waits, saturating
    // at 15, cleared on grant. The highest effective priority wins; equals
    // share round-robin. A QoS-0 requester behind a QoS-15 one is served
    // after at most 15 * 2**4 cycles of waiting, never starved.
    logic [7:0] ddr_aw_arb_age_0;
    wire  [7:0] ddr_aw_arb_boost_0 = ddr_aw_arb_age_0 >> 4;
    wire  [4:0] ddr_aw_arb_sum_0 = 5'(cpu_32b_aw.qos) + ((ddr_aw_arb_boost_0 > 8'd15) ? 5'd15 : 5'(ddr_aw_arb_boost_0[3:0]));
