    wire  [3:0] ddr_aw_arb_cand_0 = ddr_aw_arb_req[0] ? ddr_aw_arb_eff_0 : 4'h0;
    logic [7:0] ddr_aw_arb_age_1;
    wire  [7:0] ddr_aw_arb_boost_1 = ddr_aw_arb_age_1 >> 4;
    wire  [4:0] ddr_aw_arb_sum_1 = 5'(dma_32b_aw.qos) + ((ddr_aw_arb_boost_1 > 8'd15) ? 5'd15 : 5'(ddr_aw_arb_boost_1[3:0]));
    wire  [3:0] ddr_aw_arb_eff_1 = ddr_aw_arb_sum_1[4] ? 4'hF : ddr_aw_arb_sum_1[3:0];
    wire  [3:0] ddr_aw_arb_cand_1 = ddr_aw_arb_req[1] ? ddr_aw_arb_eff_1 : 4'h0;
    wire  [3:0] ddr_aw_arb_best = ((ddr_aw_arb_cand_1 > ddr_aw_arb_cand_0) ? ddr_aw_arb_cand_1 : ddr_aw_arb_cand_0);
    wire  [1:0] ddr_aw_arb_elig = {(ddr_aw_arb_req[1] && (ddr_aw_arb_eff_1 == ddr_aw_arb_best)), (ddr_aw_arb_req[0] && (ddr_aw_arb_eff_0 == ddr_aw_arb_best))};
    wire [0:0] ddr_aw_arb_pick = (ddr_aw_arb_rr == 1'd0) ? (ddr_aw_arb_elig[0] ? 1'd0 : 1'd1) : 
        ddr_aw_arb_elig[1] ? 1'd1 : 1'd0;
    wire ddr_aw_arb_gnt_valid = ddr_aw_arb_locked || (|ddr_aw_arb_req);
    wire [0:0] ddr_aw_arb_gnt = ddr_aw_arb_locked ? ddr_aw_arb_lock : ddr_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ddr_aw_arb_lock   <= '0;
            ddr_aw_arb_rr     <= '0;
            ddr_aw_arb_locked <= 1'b0;
            ddr_aw_arb_age_0 <= 8'd0;
            ddr_aw_arb_age_1 <= 8'd0;
        end else begin
            if (xs_ddr_axi_awvalid && xs_ddr_axi_awready) begin
                ddr_aw_arb_locked <= 1'b0;
                ddr_aw_arb_rr <= (ddr_aw_arb_gnt == 1'd1) ? 1'd0 : ddr_aw_arb_gnt + 1'b1;
            end else if (xs_ddr_axi_awvalid) begin
                ddr_aw_arb_lock   <= ddr_aw_arb_gnt;
                ddr_aw_arb_locked <= 1'b1;
            end
            if (ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 1'd0))
                ddr_aw_arb_age_0 <= 8'd0;
            else if (ddr_aw_arb_req[0] && (ddr_aw_arb_age_0 != 8'hFF))
                ddr_aw_arb_age_0 <= ddr_aw_arb_age_0 + 8'd1;
            if (ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 1'd1))
                ddr_aw_arb_age_1 <= 8'd0;
            else if (ddr_aw_arb_req[1] && (ddr_aw_arb_age_1 != 8'hFF))
                ddr_aw_arb_age_1 <= ddr_aw_arb_age_1 + 8'd1;
        end
    )
    wire cpu_32b_aw_gnt_ddr = ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 1'd0) && ddr_aw_arb_req[0];
    wire dma_32b_aw_gnt_ddr = ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 1'd1) && ddr_aw_arb_req[1];

    // AW channel (arbitrated mux across writing masters)
    assign xs_ddr_axi_awid = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw.id : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw.id : '0);
    assign xs_ddr_axi_awaddr = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw.addr : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw.addr : '0);
    assign xs_ddr_axi_awlen = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw.len : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw.len : '0);
    assign xs_ddr_axi_awsize = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw.size : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw.size : '0);
    assign xs_ddr_axi_awburst = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw.burst : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw.burst : '0);
    assign xs_ddr_axi_awlock = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw.lock : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw.lock : '0);
    assign xs_ddr_axi_awcache = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw.cache : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw.cache : '0);
    assign xs_ddr_axi_awprot = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw.prot : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw.prot : '0);
    assign xs_ddr_axi_awqos = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw.qos : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw.qos : '0);
    assign xs_ddr_axi_awregion = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw.region : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw.region : '0);
    assign xs_ddr_axi_awuser = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw.user : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw.user : '0);
    assign xs_ddr_axi_awvalid = cpu_32b_aw_gnt_ddr || dma_32b_aw_gnt_ddr;

    // W owner FIFO: slave-side AW accept order owns the W channel
    logic [0:0] ddr_wowner_mem [16];
    logic [4:0] ddr_wowner_wptr, ddr_wowner_rptr;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ddr_wowner_wptr <= '0;
            ddr_wowner_rptr <= '0;
        end else begin
            if (xs_ddr_axi_awvalid && xs_ddr_axi_awready) begin
                ddr_wowner_mem[ddr_wowner_wptr[3:0]] <= ddr_aw_arb_gnt;
                ddr_wowner_wptr <= ddr_wowner_wptr + 1'b1;
            end
            if (xs_ddr_axi_wvalid && xs_ddr_axi_wready && xs_ddr_axi_wlast) begin
                ddr_wowner_rptr <= ddr_wowner_rptr + 1'b1;
            end
        end
    )
    wire ddr_wowner_valid = (ddr_wowner_wptr != ddr_wowner_rptr);
    wire [0:0] ddr_wowner_head = ddr_wowner_mem[ddr_wowner_rptr[3:0]];
    assign cpu_32b_w_sel_ddr = ddr_wowner_valid && (ddr_wowner_head == 1'd0) && cpu_32b_w_to_ddr;
    assign dma_32b_w_sel_ddr = ddr_wowner_valid && (ddr_wowner_head == 1'd1) && dma_32b_w_to_ddr;

    // W channel (owner-gated mux across writing masters)
    assign xs_ddr_axi_wdata = ((cpu_32b_w_sel_ddr && cpu_32b_wvalid) ? cpu_32b_w.data : '0) |
        ((dma_32b_w_sel_ddr && dma_32b_wvalid) ? dma_32b_w.data : '0);
    assign xs_ddr_axi_wstrb = ((cpu_32b_w_sel_ddr && cpu_32b_wvalid) ? cpu_32b_w.strb : '0) |
        ((dma_32b_w_sel_ddr && dma_32b_wvalid) ? dma_32b_w.strb : '0);
    assign xs_ddr_axi_wlast = ((cpu_32b_w_sel_ddr && cpu_32b_wvalid) ? cpu_32b_w.last : '0) |
        ((dma_32b_w_sel_ddr && dma_32b_wvalid) ? dma_32b_w.last : '0);
    assign xs_ddr_axi_wuser = ((cpu_32b_w_sel_ddr && cpu_32b_wvalid) ? cpu_32b_w.user : '0) |
        ((dma_32b_w_sel_ddr && dma_32b_wvalid) ? dma_32b_w.user : '0);
    assign xs_ddr_axi_wvalid = (cpu_32b_w_sel_ddr && cpu_32b_wvalid) || (dma_32b_w_sel_ddr && dma_32b_wvalid);

    // Bready (slave → owning master, by bid_bridge_id)
    assign xs_ddr_axi_bready = ((xs_ddr_axi_bid_bridge_id == 0) && xs_ddr_axi_bid_valid ? cpu_32b_bready : '0) |
        ((xs_ddr_axi_bid_bridge_id == 1) && xs_ddr_axi_bid_valid ? dma_32b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign xs_ddr_axi_bridge_id_aw = (cpu_32b_aw_gnt_ddr ? cpu_bridge_id_aw : '0) |
        (dma_32b_aw_gnt_ddr ? dma_bridge_id_aw : '0);

    // ---- AR arbiter for ddr: QoS + aging, round-robin ties, lock until handshake ----
    logic [1:0] ddr_ar_arb_req;
    assign ddr_ar_arb_req = {dma_32b_ar_to_ddr && dma_32b_arvalid, cpu_32b_ar_to_ddr && cpu_32b_arvalid};
    logic [0:0] ddr_ar_arb_lock, ddr_ar_arb_rr;
    logic ddr_ar_arb_locked;
    // QoS with aging (BRIDGE-017): effective priority = AxQOS + age,
    // age climbing one level every 2**4 cycles a request waits, saturating
    // at 15, cleared on grant. The highest effective priority wins; equals
    // share round-robin. A QoS-0 requester behind a QoS-15 one is served
    // after at most 15 * 2**4 cycles of waiting, never starved.
    logic [7:0] ddr_ar_arb_age_0;
    wire  [7:0] ddr_ar_arb_boost_0 = ddr_ar_arb_age_0 >> 4;
    wire  [4:0] ddr_ar_arb_sum_0 = 5'(cpu_32b_ar.qos) + ((ddr_ar_arb_boost_0 > 8'd15) ? 5'd15 : 5'(ddr_ar_arb_boost_0[3:0]));
    wire  [3:0] ddr_ar_arb_eff_0 = ddr_ar_arb_sum_0[4] ? 4'hF : ddr_ar_arb_sum_0[3:0];
    wire  [3:0] ddr_ar_arb_cand_0 = ddr_ar_arb_req[0] ? ddr_ar_arb_eff_0 : 4'h0;
    logic [7:0] ddr_ar_arb_age_1;
    wire  [7:0] ddr_ar_arb_boost_1 = ddr_ar_arb_age_1 >> 4;
    wire  [4:0] ddr_ar_arb_sum_1 = 5'(dma_32b_ar.qos) + ((ddr_ar_arb_boost_1 > 8'd15) ? 5'd15 : 5'(ddr_ar_arb_boost_1[3:0]));
    wire  [3:0] ddr_ar_arb_eff_1 = ddr_ar_arb_sum_1[4] ? 4'hF : ddr_ar_arb_sum_1[3:0];
    wire  [3:0] ddr_ar_arb_cand_1 = ddr_ar_arb_req[1] ? ddr_ar_arb_eff_1 : 4'h0;
    wire  [3:0] ddr_ar_arb_best = ((ddr_ar_arb_cand_1 > ddr_ar_arb_cand_0) ? ddr_ar_arb_cand_1 : ddr_ar_arb_cand_0);
    wire  [1:0] ddr_ar_arb_elig = {(ddr_ar_arb_req[1] && (ddr_ar_arb_eff_1 == ddr_ar_arb_best)), (ddr_ar_arb_req[0] && (ddr_ar_arb_eff_0 == ddr_ar_arb_best))};
    wire [0:0] ddr_ar_arb_pick = (ddr_ar_arb_rr == 1'd0) ? (ddr_ar_arb_elig[0] ? 1'd0 : 1'd1) : 
        ddr_ar_arb_elig[1] ? 1'd1 : 1'd0;
    wire ddr_ar_arb_gnt_valid = ddr_ar_arb_locked || (|ddr_ar_arb_req);
    wire [0:0] ddr_ar_arb_gnt = ddr_ar_arb_locked ? ddr_ar_arb_lock : ddr_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ddr_ar_arb_lock   <= '0;
            ddr_ar_arb_rr     <= '0;
            ddr_ar_arb_locked <= 1'b0;
            ddr_ar_arb_age_0 <= 8'd0;
            ddr_ar_arb_age_1 <= 8'd0;
        end else begin
            if (xs_ddr_axi_arvalid && xs_ddr_axi_arready) begin
                ddr_ar_arb_locked <= 1'b0;
                ddr_ar_arb_rr <= (ddr_ar_arb_gnt == 1'd1) ? 1'd0 : ddr_ar_arb_gnt + 1'b1;
            end else if (xs_ddr_axi_arvalid) begin
                ddr_ar_arb_lock   <= ddr_ar_arb_gnt;
                ddr_ar_arb_locked <= 1'b1;
            end
            if (ddr_ar_arb_gnt_valid && (ddr_ar_arb_gnt == 1'd0))
                ddr_ar_arb_age_0 <= 8'd0;
            else if (ddr_ar_arb_req[0] && (ddr_ar_arb_age_0 != 8'hFF))
                ddr_ar_arb_age_0 <= ddr_ar_arb_age_0 + 8'd1;
            if (ddr_ar_arb_gnt_valid && (ddr_ar_arb_gnt == 1'd1))
                ddr_ar_arb_age_1 <= 8'd0;
            else if (ddr_ar_arb_req[1] && (ddr_ar_arb_age_1 != 8'hFF))
                ddr_ar_arb_age_1 <= ddr_ar_arb_age_1 + 8'd1;
