    // W owner FIFO: slave-side AW accept order owns the W channel
    logic [0:0] subtractive_wowner_mem [16];
    logic [4:0] subtractive_wowner_wptr, subtractive_wowner_rptr;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_wowner_wptr <= '0;
            subtractive_wowner_rptr <= '0;
        end else begin
            if (xs_subtractive_axi_awvalid && xs_subtractive_axi_awready) begin
                subtractive_wowner_mem[subtractive_wowner_wptr[3:0]] <= subtractive_aw_arb_gnt;
                subtractive_wowner_wptr <= subtractive_wowner_wptr + 1'b1;
            end
            if (xs_subtractive_axi_wvalid && xs_subtractive_axi_wready && xs_subtractive_axi_wlast) begin
                subtractive_wowner_rptr <= subtractive_wowner_rptr + 1'b1;
            end
        end
    )
    wire subtractive_wowner_valid = (subtractive_wowner_wptr != subtractive_wowner_rptr);
    wire [0:0] subtractive_wowner_head = subtractive_wowner_mem[subtractive_wowner_rptr[3:0]];
    assign cpu_32b_w_sel_subtractive = subtractive_wowner_valid && (subtractive_wowner_head == 1'd0) && cpu_32b_w_to_subtractive;
    assign dma_32b_w_sel_subtractive = subtractive_wowner_valid && (subtractive_wowner_head == 1'd1) && dma_32b_w_to_subtractive;

    // W channel (owner-gated mux across writing masters)
    assign xs_subtractive_axi_wdata = ((cpu_32b_w_sel_subtractive && cpu_32b_wvalid) ? cpu_32b_w.data : '0) |
        ((dma_32b_w_sel_subtractive && dma_32b_wvalid) ? dma_32b_w.data : '0);
    assign xs_subtractive_axi_wstrb = ((cpu_32b_w_sel_subtractive && cpu_32b_wvalid) ? cpu_32b_w.strb : '0) |
        ((dma_32b_w_sel_subtractive && dma_32b_wvalid) ? dma_32b_w.strb : '0);
    assign xs_subtractive_axi_wlast = ((cpu_32b_w_sel_subtractive && cpu_32b_wvalid) ? cpu_32b_w.last : '0) |
        ((dma_32b_w_sel_subtractive && dma_32b_wvalid) ? dma_32b_w.last : '0);
    assign xs_subtractive_axi_wuser = ((cpu_32b_w_sel_subtractive && cpu_32b_wvalid) ? cpu_32b_w.user : '0) |
        ((dma_32b_w_sel_subtractive && dma_32b_wvalid) ? dma_32b_w.user : '0);
    assign xs_subtractive_axi_wvalid = (cpu_32b_w_sel_subtractive && cpu_32b_wvalid) || (dma_32b_w_sel_subtractive && dma_32b_wvalid);

    // Bready (slave → owning master, by bid_bridge_id)
    assign xs_subtractive_axi_bready = ((xs_subtractive_axi_bid_bridge_id == 0) && xs_subtractive_axi_bid_valid ? cpu_32b_bready : '0) |
        ((xs_subtractive_axi_bid_bridge_id == 1) && xs_subtractive_axi_bid_valid ? dma_32b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign xs_subtractive_axi_bridge_id_aw = (cpu_32b_aw_gnt_subtractive ? cpu_bridge_id_aw : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_bridge_id_aw : '0);

    // ---- AR arbiter for subtractive: QoS + aging, round-robin ties, lock until handshake ----
    logic [1:0] subtractive_ar_arb_req;
    assign subtractive_ar_arb_req = {dma_32b_ar_to_subtractive && dma_32b_arvalid, cpu_32b_ar_to_subtractive && cpu_32b_arvalid};
    logic [0:0] subtractive_ar_arb_lock, subtractive_ar_arb_rr;
    logic subtractive_ar_arb_locked;
    // QoS with aging (BRIDGE-017): effective priority = AxQOS + age,
    // age climbing one level every 2**4 cycles a request waits, saturating
    // at 15, cleared on grant. The highest effective priority wins; equals
    // share round-robin. A QoS-0 requester behind a QoS-15 one is served
    // after at most 15 * 2**4 cycles of waiting, never starved.
    logic [7:0] subtractive_ar_arb_age_0;
    wire  [7:0] subtractive_ar_arb_boost_0 = subtractive_ar_arb_age_0 >> 4;
    wire  [4:0] subtractive_ar_arb_sum_0 = 5'(cpu_32b_ar.qos) + ((subtractive_ar_arb_boost_0 > 8'd15) ? 5'd15 : 5'(subtractive_ar_arb_boost_0[3:0]));
    wire  [3:0] subtractive_ar_arb_eff_0 = subtractive_ar_arb_sum_0[4] ? 4'hF : subtractive_ar_arb_sum_0[3:0];
    wire  [3:0] subtractive_ar_arb_cand_0 = subtractive_ar_arb_req[0] ? subtractive_ar_arb_eff_0 : 4'h0;
    logic [7:0] subtractive_ar_arb_age_1;
    wire  [7:0] subtractive_ar_arb_boost_1 = subtractive_ar_arb_age_1 >> 4;
    wire  [4:0] subtractive_ar_arb_sum_1 = 5'(dma_32b_ar.qos) + ((subtractive_ar_arb_boost_1 > 8'd15) ? 5'd15 : 5'(subtractive_ar_arb_boost_1[3:0]));
    wire  [3:0] subtractive_ar_arb_eff_1 = subtractive_ar_arb_sum_1[4] ? 4'hF : subtractive_ar_arb_sum_1[3:0];
    wire  [3:0] subtractive_ar_arb_cand_1 = subtractive_ar_arb_req[1] ? subtractive_ar_arb_eff_1 : 4'h0;
    wire  [3:0] subtractive_ar_arb_best = ((subtractive_ar_arb_cand_1 > subtractive_ar_arb_cand_0) ? subtractive_ar_arb_cand_1 : subtractive_ar_arb_cand_0);
    wire  [1:0] subtractive_ar_arb_elig = {(subtractive_ar_arb_req[1] && (subtractive_ar_arb_eff_1 == subtractive_ar_arb_best)), (subtractive_ar_arb_req[0] && (subtractive_ar_arb_eff_0 == subtractive_ar_arb_best))};
    wire [0:0] subtractive_ar_arb_pick = (subtractive_ar_arb_rr == 1'd0) ? (subtractive_ar_arb_elig[0] ? 1'd0 : 1'd1) : 
        subtractive_ar_arb_elig[1] ? 1'd1 : 1'd0;
    wire subtractive_ar_arb_gnt_valid = subtractive_ar_arb_locked || (|subtractive_ar_arb_req);
    wire [0:0] subtractive_ar_arb_gnt = subtractive_ar_arb_locked ? subtractive_ar_arb_lock : subtractive_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_ar_arb_lock   <= '0;
            subtractive_ar_arb_rr     <= '0;
            subtractive_ar_arb_locked <= 1'b0;
            subtractive_ar_arb_age_0 <= 8'd0;
            subtractive_ar_arb_age_1 <= 8'd0;
        end else begin
            if (xs_subtractive_axi_arvalid && xs_subtractive_axi_arready) begin
                subtractive_ar_arb_locked <= 1'b0;
                subtractive_ar_arb_rr <= (subtractive_ar_arb_gnt == 1'd1) ? 1'd0 : subtractive_ar_arb_gnt + 1'b1;
            end else if (xs_subtractive_axi_arvalid) begin
                subtractive_ar_arb_lock   <= subtractive_ar_arb_gnt;
                subtractive_ar_arb_locked <= 1'b1;
            end
            if (subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd0))
                subtractive_ar_arb_age_0 <= 8'd0;
            else if (subtractive_ar_arb_req[0] && (subtractive_ar_arb_age_0 != 8'hFF))
                subtractive_ar_arb_age_0 <= subtractive_ar_arb_age_0 + 8'd1;
            if (subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd1))
                subtractive_ar_arb_age_1 <= 8'd0;
            else if (subtractive_ar_arb_req[1] && (subtractive_ar_arb_age_1 != 8'hFF))
                subtractive_ar_arb_age_1 <= subtractive_ar_arb_age_1 + 8'd1;
        end
    )
    wire cpu_32b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd0) && subtractive_ar_arb_req[0];
    wire dma_32b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd1) && subtractive_ar_arb_req[1];

    // AR channel (arbitrated mux across reading masters)
    assign xs_subtractive_axi_arid = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar.id : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar.id : '0);
    assign xs_subtractive_axi_araddr = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar.addr : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar.addr : '0);
    assign xs_subtractive_axi_arlen = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar.len : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar.len : '0);
    assign xs_subtractive_axi_arsize = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar.size : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar.size : '0);
    assign xs_subtractive_axi_arburst = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar.burst : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar.burst : '0);
    assign xs_subtractive_axi_arlock = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar.lock : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar.lock : '0);
    assign xs_subtractive_axi_arcache = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar.cache : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar.cache : '0);
    assign xs_subtractive_axi_arprot = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar.prot : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar.prot : '0);
    assign xs_subtractive_axi_arqos = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar.qos : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar.qos : '0);
    assign xs_subtractive_axi_arregion = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar.region : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar.region : '0);
    assign xs_subtractive_axi_aruser = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar.user : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar.user : '0);
    assign xs_subtractive_axi_arvalid = cpu_32b_ar_gnt_subtractive || dma_32b_ar_gnt_subtractive;

    // Rready (slave → owning master, by rid_bridge_id)
    assign xs_subtractive_axi_rready = ((xs_subtractive_axi_rid_bridge_id == 0) && xs_subtractive_axi_rid_valid ? cpu_32b_rready : '0) |
        ((xs_subtractive_axi_rid_bridge_id == 1) && xs_subtractive_axi_rid_valid ? dma_32b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign xs_subtractive_axi_bridge_id_ar = (cpu_32b_ar_gnt_subtractive ? cpu_bridge_id_ar : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_bridge_id_ar : '0);


    // ================================================================
    // W destination FIFOs (per master width-path)
    // ================================================================
    // cpu 32b path -> ddr, sram, subtractive
    logic [1:0] cpu_32b_wdest_mem [16];
    logic [4:0] cpu_32b_wdest_wptr, cpu_32b_wdest_rptr;
    wire [1:0] cpu_32b_wdest_enc = cpu_32b_aw_to_sram ? 2'd1 : cpu_32b_aw_to_subtractive ? 2'd2 : 2'd0;
    wire cpu_32b_wdest_push = cpu_32b_awvalid && cpu_32b_awready;
    wire cpu_32b_wdest_pop  = cpu_32b_wvalid && cpu_32b_wready && cpu_32b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_32b_wdest_wptr <= '0;
            cpu_32b_wdest_rptr <= '0;
        end else begin
            if (cpu_32b_wdest_push) begin
                cpu_32b_wdest_mem[cpu_32b_wdest_wptr[3:0]] <= cpu_32b_wdest_enc;
                cpu_32b_wdest_wptr <= cpu_32b_wdest_wptr + 1'b1;
            end
            if (cpu_32b_wdest_pop) begin
                cpu_32b_wdest_rptr <= cpu_32b_wdest_rptr + 1'b1;
            end
        end
    )
    wire cpu_32b_wdest_valid = (cpu_32b_wdest_wptr != cpu_32b_wdest_rptr);
    wire [1:0] cpu_32b_wdest_head = cpu_32b_wdest_mem[cpu_32b_wdest_rptr[3:0]];
    assign cpu_32b_w_to_ddr = cpu_32b_wdest_valid && (cpu_32b_wdest_head == 2'd0);
    assign cpu_32b_w_to_sram = cpu_32b_wdest_valid && (cpu_32b_wdest_head == 2'd1);
    assign cpu_32b_w_to_subtractive = cpu_32b_wdest_valid && (cpu_32b_wdest_head == 2'd2);

    // dma 32b path -> ddr, sram, subtractive
    logic [1:0] dma_32b_wdest_mem [16];
    logic [4:0] dma_32b_wdest_wptr, dma_32b_wdest_rptr;
    wire [1:0] dma_32b_wdest_enc = dma_32b_aw_to_sram ? 2'd1 : dma_32b_aw_to_subtractive ? 2'd2 : 2'd0;
    wire dma_32b_wdest_push = dma_32b_awvalid && dma_32b_awready;
    wire dma_32b_wdest_pop  = dma_32b_wvalid && dma_32b_wready && dma_32b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            dma_32b_wdest_wptr <= '0;
            dma_32b_wdest_rptr <= '0;
        end else begin
            if (dma_32b_wdest_push) begin
                dma_32b_wdest_mem[dma_32b_wdest_wptr[3:0]] <= dma_32b_wdest_enc;
                dma_32b_wdest_wptr <= dma_32b_wdest_wptr + 1'b1;
            end
            if (dma_32b_wdest_pop) begin
                dma_32b_wdest_rptr <= dma_32b_wdest_rptr + 1'b1;
            end
        end
    )
    wire dma_32b_wdest_valid = (dma_32b_wdest_wptr != dma_32b_wdest_rptr);
    wire [1:0] dma_32b_wdest_head = dma_32b_wdest_mem[dma_32b_wdest_rptr[3:0]];
    assign dma_32b_w_to_ddr = dma_32b_wdest_valid && (dma_32b_wdest_head == 2'd0);
    assign dma_32b_w_to_sram = dma_32b_wdest_valid && (dma_32b_wdest_head == 2'd1);
    assign dma_32b_w_to_subtractive = dma_32b_wdest_valid && (dma_32b_wdest_head == 2'd2);

    // ================================================================
    // Response MUXes (OR together all slave responses)
    // ================================================================

    // Master: cpu, Width path: 32b
    assign cpu_32b_awready = 
        (cpu_32b_aw_gnt_ddr ? xs_ddr_axi_awready : '0) |
        (cpu_32b_aw_gnt_sram ? xs_sram_axi_awready : '0) |
        (cpu_32b_aw_gnt_subtractive ? xs_subtractive_axi_awready : '0);

    assign cpu_32b_wready = 
        (cpu_32b_w_sel_ddr ? xs_ddr_axi_wready : '0) |
        (cpu_32b_w_sel_sram ? xs_sram_axi_wready : '0) |
        (cpu_32b_w_sel_subtractive ? xs_subtractive_axi_wready : '0);

    assign cpu_32b_b.id = 
        ((xs_ddr_axi_bid_bridge_id == 0) && xs_ddr_axi_bid_valid ? xs_ddr_axi_bid : '0) |
        ((xs_sram_axi_bid_bridge_id == 0) && xs_sram_axi_bid_valid ? xs_sram_axi_bid : '0) |
        ((xs_subtractive_axi_bid_bridge_id == 0) && xs_subtractive_axi_bid_valid ? xs_subtractive_axi_bid : '0);

    assign cpu_32b_b.resp = 
        ((xs_ddr_axi_bid_bridge_id == 0) && xs_ddr_axi_bid_valid ? xs_ddr_axi_bresp : '0) |
        ((xs_sram_axi_bid_bridge_id == 0) && xs_sram_axi_bid_valid ? xs_sram_axi_bresp : '0) |
        ((xs_subtractive_axi_bid_bridge_id == 0) && xs_subtractive_axi_bid_valid ? xs_subtractive_axi_bresp : '0);

    assign cpu_32b_b.user = 
        ((xs_ddr_axi_bid_bridge_id == 0) && xs_ddr_axi_bid_valid ? xs_ddr_axi_buser : '0) |
        ((xs_sram_axi_bid_bridge_id == 0) && xs_sram_axi_bid_valid ? xs_sram_axi_buser : '0) |
        ((xs_subtractive_axi_bid_bridge_id == 0) && xs_subtractive_axi_bid_valid ? xs_subtractive_axi_buser : '0);

    assign cpu_32b_bvalid = 
        ((xs_ddr_axi_bid_bridge_id == 0) && xs_ddr_axi_bid_valid ? xs_ddr_axi_bvalid : '0) |
        ((xs_sram_axi_bid_bridge_id == 0) && xs_sram_axi_bid_valid ? xs_sram_axi_bvalid : '0) |
        ((xs_subtractive_axi_bid_bridge_id == 0) && xs_subtractive_axi_bid_valid ? xs_subtractive_axi_bvalid : '0);

    assign cpu_32b_arready = 
        (cpu_32b_ar_gnt_ddr ? xs_ddr_axi_arready : '0) |
        (cpu_32b_ar_gnt_sram ? xs_sram_axi_arready : '0) |
        (cpu_32b_ar_gnt_subtractive ? xs_subtractive_axi_arready : '0);

    assign cpu_32b_r.id = 
        ((xs_ddr_axi_rid_bridge_id == 0) && xs_ddr_axi_rid_valid ? xs_ddr_axi_rid : '0) |
        ((xs_sram_axi_rid_bridge_id == 0) && xs_sram_axi_rid_valid ? xs_sram_axi_rid : '0) |
        ((xs_subtractive_axi_rid_bridge_id == 0) && xs_subtractive_axi_rid_valid ? xs_subtractive_axi_rid : '0);

    assign cpu_32b_r.data = 
        ((xs_ddr_axi_rid_bridge_id == 0) && xs_ddr_axi_rid_valid ? xs_ddr_axi_rdata : 32'b0) |
        ((xs_sram_axi_rid_bridge_id == 0) && xs_sram_axi_rid_valid ? xs_sram_axi_rdata : 32'b0) |
        ((xs_subtractive_axi_rid_bridge_id == 0) && xs_subtractive_axi_rid_valid ? xs_subtractive_axi_rdata : 32'b0);

    assign cpu_32b_r.resp = 
        ((xs_ddr_axi_rid_bridge_id == 0) && xs_ddr_axi_rid_valid ? xs_ddr_axi_rresp : '0) |
        ((xs_sram_axi_rid_bridge_id == 0) && xs_sram_axi_rid_valid ? xs_sram_axi_rresp : '0) |
        ((xs_subtractive_axi_rid_bridge_id == 0) && xs_subtractive_axi_rid_valid ? xs_subtractive_axi_rresp : '0);

    assign cpu_32b_r.last = 
        ((xs_ddr_axi_rid_bridge_id == 0) && xs_ddr_axi_rid_valid ? xs_ddr_axi_rlast : '0) |
        ((xs_sram_axi_rid_bridge_id == 0) && xs_sram_axi_rid_valid ? xs_sram_axi_rlast : '0) |
        ((xs_subtractive_axi_rid_bridge_id == 0) && xs_subtractive_axi_rid_valid ? xs_subtractive_axi_rlast : '0);

    assign cpu_32b_r.user = 
        ((xs_ddr_axi_rid_bridge_id == 0) && xs_ddr_axi_rid_valid ? xs_ddr_axi_ruser : '0) |
        ((xs_sram_axi_rid_bridge_id == 0) && xs_sram_axi_rid_valid ? xs_sram_axi_ruser : '0) |
        ((xs_subtractive_axi_rid_bridge_id == 0) && xs_subtractive_axi_rid_valid ? xs_subtractive_axi_ruser : '0);

    assign cpu_32b_rvalid = 
        ((xs_ddr_axi_rid_bridge_id == 0) && xs_ddr_axi_rid_valid ? xs_ddr_axi_rvalid : '0) |
        ((xs_sram_axi_rid_bridge_id == 0) && xs_sram_axi_rid_valid ? xs_sram_axi_rvalid : '0) |
        ((xs_subtractive_axi_rid_bridge_id == 0) && xs_subtractive_axi_rid_valid ? xs_subtractive_axi_rvalid : '0);

`ifndef SYNTHESIS
    // synthesis translate_off
    always_ff @(posedge aclk) begin
        if (aresetn && $countones({((xs_ddr_axi_rid_bridge_id == 0) && xs_ddr_axi_rid_valid), ((xs_sram_axi_rid_bridge_id == 0) && xs_sram_axi_rid_valid), ((xs_subtractive_axi_rid_bridge_id == 0) && xs_subtractive_axi_rid_valid)}) > 1) begin
            $error("%m: response mux for master cpu (32b) has %0d slaves selected at once; ",
                   "the single-outstanding-target invariant is broken and the R payload is OR-merged",
                   $countones({((xs_ddr_axi_rid_bridge_id == 0) && xs_ddr_axi_rid_valid), ((xs_sram_axi_rid_bridge_id == 0) && xs_sram_axi_rid_valid), ((xs_subtractive_axi_rid_bridge_id == 0) && xs_subtractive_axi_rid_valid)}));
        end
    end
    // synthesis translate_on
`endif


    // Master: dma, Width path: 32b
    assign dma_32b_awready = 
        (dma_32b_aw_gnt_ddr ? xs_ddr_axi_awready : '0) |
        (dma_32b_aw_gnt_sram ? xs_sram_axi_awready : '0) |
        (dma_32b_aw_gnt_subtractive ? xs_subtractive_axi_awready : '0);

    assign dma_32b_wready = 
        (dma_32b_w_sel_ddr ? xs_ddr_axi_wready : '0) |
        (dma_32b_w_sel_sram ? xs_sram_axi_wready : '0) |
        (dma_32b_w_sel_subtractive ? xs_subtractive_axi_wready : '0);

    assign dma_32b_b.id = 
        ((xs_ddr_axi_bid_bridge_id == 1) && xs_ddr_axi_bid_valid ? xs_ddr_axi_bid : '0) |
        ((xs_sram_axi_bid_bridge_id == 1) && xs_sram_axi_bid_valid ? xs_sram_axi_bid : '0) |
        ((xs_subtractive_axi_bid_bridge_id == 1) && xs_subtractive_axi_bid_valid ? xs_subtractive_axi_bid : '0);

    assign dma_32b_b.resp = 
        ((xs_ddr_axi_bid_bridge_id == 1) && xs_ddr_axi_bid_valid ? xs_ddr_axi_bresp : '0) |
        ((xs_sram_axi_bid_bridge_id == 1) && xs_sram_axi_bid_valid ? xs_sram_axi_bresp : '0) |
        ((xs_subtractive_axi_bid_bridge_id == 1) && xs_subtractive_axi_bid_valid ? xs_subtractive_axi_bresp : '0);

    assign dma_32b_b.user = 
        ((xs_ddr_axi_bid_bridge_id == 1) && xs_ddr_axi_bid_valid ? xs_ddr_axi_buser : '0) |
        ((xs_sram_axi_bid_bridge_id == 1) && xs_sram_axi_bid_valid ? xs_sram_axi_buser : '0) |
